html:
{#- POS Invoice Thermal: POS Invoice Version 2's bill for an 80mm thermal (receipt) printer — same store header,
    walk-in line, items (with each line's GST), totals and terms, laid out one under another in the 72mm print width
    (docs/pos-store-scope.md › Print formats). Black only: thermal printers print no colour or grey. -#}
{%- set dacs_base = frappe.utils.get_url() -%}
<style>
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Regular.ttf') format('truetype'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Bold.ttf') format('truetype'); font-weight: bold; font-style: normal; }
body, body * { font-family: Arial !important; color: #000 !important; }
/* PDF: an 80mm wide page (wkhtmltopdf reads page-width / page-height / margins from this rule, frappe.utils.pdf);
   a long bill continues on the next 297mm */
.print-format { page-width: 80mm; page-height: 297mm; margin-top: 3mm; margin-bottom: 3mm; margin-left: 4mm; margin-right: 4mm; }
/* browser print to the receipt printer: no page margin — the printer's own roll width decides the paper */
@page { margin: 0; }
/* The bill sits at the LEFT edge, 70mm wide (68mm of print + 1mm each side). Centred on the browser's page
   (80mm roll) it started 4mm in, and a print head that prints from the left edge for 72mm cut the last
   4-5mm (Amount column, totals) — seen at Rajajinagar, 12-11-2026. */
@media print { html, body, .print-format-gutter { margin: 0 !important; padding: 0 !important; } }
html body .print-format { width: 70mm !important; max-width: 70mm !important; min-height: 0 !important; margin: 0 !important; padding: 2mm 1mm !important; box-sizing: border-box !important; font-size: 8pt; }
.dacs-r { width: 100%; line-height: 1.25; font-size: 8pt; }
.dacs-r table { width: 100%; border-collapse: collapse; }
/* Frappe's print styles pad every cell and shade table headers — this bill sets its own */
.dacs-r td, .dacs-r th { padding: 0 !important; border: none !important; background: none !important; vertical-align: top; font-size: 8pt; line-height: 1.25; }
.dacs-c { text-align: center; }
.dacs-n { text-align: right; white-space: nowrap; }
.dacs-line { border-top: 1px solid #000; margin: 3px 0; }
.dacs-dash { border-top: 1px dashed #000; margin: 3px 0; }
/* items: each item its own block with room around it — S.No and name, then HSN · GST % / qty / rate / amount
   (with GST), discount below */
.dacs-it th { font-size: 7.5pt !important; font-weight: bold; padding: 2px 0 0 !important; }
.dacs-it td { font-size: 8pt; }
.dacs-it .nm td { padding-top: 5px !important; font-weight: bold; overflow-wrap: anywhere; }
.dacs-it .dt td { padding: 1px 0 5px !important; }
.dacs-it .h2 th { border-bottom: 1px solid #000 !important; padding-top: 0 !important; }
.dacs-it .ds td { padding: 0 0 5px !important; font-size: 7.5pt; }
/* one dashed line under each item, drawn on a div: wkhtmltopdf drew a dashed table-cell border solid in places */
.dacs-it .sep td { line-height: 0; font-size: 0 !important; }
.dacs-it .sep div { border-top: 1px dashed #000; }
.dacs-tot td { padding: 1px 0 !important; }
.dacs-tot .grand td { font-size: 10.5pt !important; font-weight: bold; padding: 3px 0 !important; border-top: 1px solid #000 !important; border-bottom: 1px solid #000 !important; }
.dacs-terms { font-size: 6.5pt; line-height: 1.2; text-align: left; }
.dacs-terms p, .dacs-terms div, .dacs-terms br { margin: 0 !important; padding: 0 !important; }
</style>
{# Store address comes from the Address linked to the bill's warehouse (POS Profile › Warehouse), so each store prints its own address #}
{% set store_wh = doc.set_warehouse or (frappe.db.get_value("POS Profile", doc.pos_profile, "warehouse") if doc.pos_profile else None) %}
{% set address_doc = None %}
{% if store_wh %}
    {% set wh_address = frappe.get_all("Address", filters={"link_doctype": "Warehouse", "link_name": store_wh, "disabled": 0}, fields=["name"], limit=1) %}
    {% if wh_address %}{% set address_doc = frappe.get_doc("Address", wh_address[0].name) %}{% endif %}
{% endif %}
{%- macro money(v) -%}{{ frappe.utils.fmt_money(v, currency=doc.currency) }}{%- endmacro -%}
<div class="dacs-r">

<!-- Header: logo, company, store address, contacts, GST / PAN / MSME / Landline -->
<div class="dacs-c">
    <img src="/files/Dacs inc Logo.jpeg" style="width:40px; height:40px; object-fit:contain;"><br>
    <div style="font-size:11pt; font-weight:bold; margin-top:2px;">{{ doc.company }}</div>
    <div style="font-size:7pt; line-height:1.3; margin-top:2px;">
        {% if address_doc %}
            {{ address_doc.address_line1 or "" }}{% if address_doc.address_line2 %}, {{ address_doc.address_line2 }}{% endif %}, {{ address_doc.city or "" }} - {{ address_doc.pincode or "" }}<br>
        {% endif %}
        customercare@dacsinc.in<br>
        online.www.dacsincstore.in<br>
        <strong>G.S.T. :</strong> {{ (address_doc and address_doc.gstin) or "29AAIFD5710C1ZQ" }} &nbsp; <strong>PAN :</strong> AAIFD5710C<br>
        <strong>MSME No :</strong> UDYAM-KR-03-00310188<br>
        <strong>Landline :</strong> 080-41206892, 080-41234140
    </div>
</div>
<div class="dacs-line"></div>
<div class="dacs-c" style="font-size:9pt; font-weight:bold;">TAX INVOICE</div>
<table style="font-size:8pt; margin-top:2px;">
    <tr><td><strong>Inv:</strong> {{ doc.name }}</td></tr>
    <tr><td><strong>Dt:</strong> {{ frappe.utils.formatdate(doc.posting_date) }}{% if doc.posting_time %} {{ frappe.utils.format_time(doc.posting_time) }}{% endif %}</td></tr>
</table>

<!-- Walk-in customer (POS Invoice › Walk-in Name / Mobile), only when filled -->
{% if doc.custom_walkin_name or doc.custom_walkin_mobile %}
<div style="font-size:8pt; margin-top:2px;">
    {% if doc.custom_walkin_name %}<strong>Customer:</strong> {{ doc.custom_walkin_name }}<br>{% endif %}
    {% if doc.custom_walkin_mobile %}<strong>Customer No:</strong> {{ doc.custom_walkin_mobile }}{% endif %}
</div>
{% endif %}
<div class="dacs-line"></div>

<!-- Items: S.No and name, then HSN · GST % / Qty / Rate / Amount (rate and amount with GST);
     MRP and discount (with GST) only on a line that has one -->
<table class="dacs-it" style="table-layout:fixed;">
    <colgroup><col style="width:34%;"><col style="width:12%;"><col style="width:27%;"><col style="width:27%;"></colgroup>
    <thead>
        <tr><th style="text-align:left;">{{ _("Item / HSN") }}</th><th class="dacs-n">{{ _("Qty") }}</th><th class="dacs-n">{{ _("Rate") }}</th><th class="dacs-n">{{ _("Amount") }}</th></tr>
        <tr class="h2"><th style="text-align:left;">{{ _("GST %") }}</th><th></th><th class="dacs-n">{{ _("incl. GST") }}</th><th class="dacs-n">{{ _("incl. GST") }}</th></tr>
    </thead>
    <tbody>
    {% for i in doc.items %}
        {%- set has_disc = (i.discount_amount or 0) | float > 0.001 or ((i.price_list_rate or 0) | float - (i.rate or 0) | float) > 0.001 -%}
        {%- set gr = (i.cgst_rate or 0) | float + (i.sgst_rate or 0) | float + (i.igst_rate or 0) | float + (i.cess_rate or 0) | float -%}
            {%- set tv = (i.taxable_value or i.net_amount or 0) | float -%}
            {%- set ga = (i.cgst_amount or 0) | float + (i.sgst_amount or 0) | float + (i.igst_amount or 0) | float + (i.cess_amount or 0) | float -%}
            {%- set gx = (1 + ga / tv) if (tv > 0 and ((i.amount or 0) | float - tv) | abs < 0.01) else (1 + gr / 100) -%}
        <tr class="nm"><td colspan="4">{{ loop.index }}. {{ i.item_code }}</td></tr>
        <tr class="dt">
            <td>{{ i.gst_hsn_code or "" }} &middot; {{ "{:g}".format(gr) }}%</td>
            <td class="dacs-n">{{ (i.qty | int) if i.qty == (i.qty | int) else i.qty }}</td>
            <td class="dacs-n">{{ frappe.utils.fmt_money((i.rate or 0) * (1 + gr / 100)) }}</td>
            <td class="dacs-n"><strong>{{ frappe.utils.fmt_money((i.amount or 0) * gx) }}</strong></td>
        </tr>
        {% if has_disc %}
        <tr class="ds"><td colspan="4">MRP {{ frappe.utils.fmt_money((i.price_list_rate or 0) * (1 + gr / 100)) }}{% if i.discount_amount %} &nbsp; Disc {{ frappe.utils.fmt_money(i.discount_amount * (1 + gr / 100)) }}{% endif %}</td></tr>
        {% endif %}
        <tr class="sep"><td colspan="4"><div></div></td></tr>
    {% endfor %}
    </tbody>
</table>

{% set ns = namespace(line_dis=0.0) %}
{% for i in doc.items %}{% set ns.line_dis = ns.line_dis + (i.discount_amount | float or 0) %}{% endfor %}
{% set ov_dis = doc.discount_amount | float or 0 %}
{% set total_qty = doc.items | sum(attribute='qty') %}
{% set pay_sum = doc.payments | sum(attribute='amount') %}
{%- set tt = namespace(incl=0.0) -%}
{%- for i in doc.items -%}
    {%- set gr = (i.cgst_rate or 0) | float + (i.sgst_rate or 0) | float + (i.igst_rate or 0) | float + (i.cess_rate or 0) | float -%}
    {%- set tv = (i.taxable_value or i.net_amount or 0) | float -%}
    {%- set ga = (i.cgst_amount or 0) | float + (i.sgst_amount or 0) | float + (i.igst_amount or 0) | float + (i.cess_amount or 0) | float -%}
    {%- set gx = (1 + ga / tv) if (tv > 0 and ((i.amount or 0) | float - tv) | abs < 0.01) else (1 + gr / 100) -%}
    {%- set tt.incl = tt.incl + (i.amount or 0) | float * gx -%}
{%- endfor -%}
{%- if doc.apply_discount_on == "Grand Total" -%}
    {%- set bill_dis = ov_dis -%}{%- set before_dis = (doc.grand_total or 0) + ov_dis -%}
{%- else -%}
    {%- set before_dis = tt.incl -%}{%- set bill_dis = tt.incl - (doc.grand_total or 0) -%}
{%- endif -%}
{%- set round_off = (doc.rounding_adjustment or 0) | float -%}
{%- set to_pay = doc.rounded_total or doc.grand_total -%}

<!-- Qty and payment -->
<table style="font-size:8pt; margin-top:3px;">
    <tr><td><strong>Qty:</strong> {{ total_qty }}</td></tr>
    {% if pay_sum > 0 %}
    <tr><td><strong>Pay:</strong> {% for p in doc.payments if p.amount > 0 %}{{ p.mode_of_payment.split('-')[0].strip() }} ({{ money(p.amount) }}){{ ", " if not loop.last }}{% endfor %}</td></tr>
    {% endif %}
</table>
<div class="dacs-dash"></div>

<!-- Totals -->
<table class="dacs-tot">
    {% if ov_dis > 0.01 %}
    <tr><td>Total</td><td class="dacs-n">{{ money(before_dis) }}</td></tr>
    <tr><td>Bill Disc (-)</td><td class="dacs-n">-{{ money(bill_dis) }}</td></tr>
    {% endif %}
    {% if round_off | abs > 0.001 %}<tr><td>Round Off</td><td class="dacs-n">{{ money(round_off) }}</td></tr>{% endif %}
    <tr class="grand"><td>TOTAL</td><td class="dacs-n">{{ money(to_pay) }}</td></tr>
</table>

<!-- Terms -->
{% if doc.terms %}
<div class="dacs-line"></div>
<div class="dacs-terms"><strong style="font-size:7pt;">Terms & Conditions:</strong>{{ doc.terms | safe }}</div>
{% endif %}

<div class="dacs-dash"></div>
<div class="dacs-c" style="font-weight:bold; font-size:8pt;">*** Thank You - Visit Again ***</div>
</div>
